<?php
function saReady():bool{try{q('SELECT id FROM student_attendance_windows LIMIT 1');return acReady();}catch(Throwable $e){return false;}}
function saReviewer(?array $u):bool{return $u&&!empty($u['active'])&&in_array($u['role'],['exam','daa','admin'],true);}
function saTutor():?array{
 $official=isset($_SESSION['user'])?one('SELECT * FROM users WHERE id=?',[(int)$_SESSION['user']]):null;if(acAdmin($official)&&hash_equals(hash('sha256',$official['password']),$_SESSION['password_version']??''))return $official;
 $s=$_SESSION['sa_identity']??[];if(($s['expires']??0)<time())return null;$u=one('SELECT * FROM users WHERE id=?',[(int)($s['id']??0)]);return $u&&!acAdmin($u)&&acTutor($u)&&hash_equals($s['version']??'',hash('sha256',$u['email'].'|'.$u['password']))?$u:null;
}
function saRequestCode(string $email):void{
 $email=strtolower(trim($email));foreach(['email:'.$email,'ip:'.($_SERVER['REMOTE_ADDR']??'')]as $i=>$key){$identity=hash('sha256','sa:'.$key);acAssert((int)q('SELECT COUNT(*) FROM login_attempts WHERE identity=? AND attempted_at>?',[$identity,time()-900])->fetchColumn()<($i===0?5:60),'Please wait 15 minutes before requesting another code.');q('INSERT INTO login_attempts(identity,attempted_at) VALUES(?,?)',[$identity,time()]);}
 unset($_SESSION['sa_code'],$_SESSION['sa_identity']);$u=one('SELECT * FROM users WHERE LOWER(email)=? AND active=1',[$email]);if(!$u||!acTutor($u)||acAdmin($u))return;
 $code=(string)random_int(100000,999999);$_SESSION['sa_code']=['id'=>$u['id'],'hash'=>password_hash($code,PASSWORD_DEFAULT),'expires'=>time()+900,'attempts'=>0,'version'=>hash('sha256',$u['email'].'|'.$u['password'])];
 q('INSERT INTO outbox(recipient,subject,body,created_at) VALUES(?,?,?,?)',[$u['email'],'CNR attendance verification code',"Your student attendance verification code is: ".$code."\n\nEnter it on the same browser where you requested it. It expires in 15 minutes. Do not share it. If you did not request it, ignore this message.",now()]);
}
function saVerifyCode(string $code):void{
 $s=$_SESSION['sa_code']??[];$_SESSION['sa_code']['attempts']=($s['attempts']??0)+1;acAssert(($s['expires']??0)>time()&&($s['attempts']??5)<5&&preg_match('/^[0-9]{6}$/D',$code)===1&&password_verify($code,$s['hash']??''),'Code is incorrect or expired. Request a new code after five attempts.');$u=one('SELECT * FROM users WHERE id=?',[$s['id']]);acAssert($u&&acTutor($u)&&hash_equals($s['version'],hash('sha256',$u['email'].'|'.$u['password'])),'Account changed. Request a new code.');session_regenerate_id(true);$_SESSION['sa_identity']=['id'=>$u['id'],'version'=>$s['version'],'expires'=>time()+7200];unset($_SESSION['sa_code']);
}
function saWindow(array $r,int $wid,bool $lock=false):array{
 acAssert(saReady(),'Attendance setup is required.');$w=one('SELECT * FROM student_attendance_windows WHERE id=?'.($lock&&db()->getAttribute(PDO::ATTR_DRIVER_NAME)==='mysql'?' FOR UPDATE':''),[$wid]);acAssert($w&&(int)$w['enabled']===1&&$w['opens_at']<=now()&&now()<$w['closes_at'],'Attendance submission is closed. Contact Exam Cell.');acAssert($w['academic_year']===$r['academic_year']&&$w['semester']===$r['semester']&&($w['programme']===''||$w['programme']===$r['programme']),'This submission period does not match the module year, semester or programme.');return $w;
}
function saPost(?array $official,string $action,array $p):int{
 acAssert(saReady(),'Run the attendance portal migration first.');
 if($action==='sa_request_code'){saRequestCode((string)($p['email']??''));$_SESSION['sa_code_form']=['email'=>strtolower(trim((string)($p['email']??''))),'requested_at'=>time()];return 0;}
 if($action==='sa_verify_code'){saVerifyCode(trim((string)($p['code']??'')));unset($_SESSION['sa_code_form']);return 0;}
 if($action==='sa_leave'){unset($_SESSION['sa_identity'],$_SESSION['sa_code'],$_SESSION['sa_code_form']);return 0;}
 if(str_starts_with($action,'sa_draft_')){$u=saTutor();acAssert((bool)$u,'Verify your registered email first.');$allowed=['create','upload','submit','discard','save_metadata'];$name=substr($action,9);acAssert(in_array($name,$allowed,true),'Unknown attendance action.');if($name==='create'){$p['kind']='attendance';}else{$r=one('SELECT kind FROM academic_records WHERE id=?',[(int)($p['id']??0)]);acAssert($r&&$r['kind']==='attendance','Attendance record required.');}return acPost($u,'ac_'.$name,$p);}
 $u=$official;db()->beginTransaction();try{
 if(in_array($action,['sa_window_create','sa_window_toggle','sa_window_edit','sa_window_delete'],true)){
  acAssert(saReviewer($u),'Only Admin / Exam Cell / DAA can manage attendance submission periods.');
  $wid=(int)($p['window_id']??0);$before=null;
  if(in_array($action,['sa_window_edit','sa_window_delete'],true)){
   $before=one('SELECT * FROM student_attendance_windows WHERE id=?'.(db()->getAttribute(PDO::ATTR_DRIVER_NAME)==='mysql'?' FOR UPDATE':''),[$wid]);
   acAssert((bool)$before,'Period not found.');
   acAssert(hash_equals(hash('sha256',acJson($before)),(string)($p['version']??'')),'Period changed. Reload before saving.');
   $reason=acText($p,'reason',1000);
  }
  if($action==='sa_window_delete'){
   acAssert(($p['confirmed']??'')==='1','Confirm deletion of the submission period.');
   q('DELETE FROM student_attendance_windows WHERE id=?',[$wid]);
   acAudit($u,0,'Attendance submission period deleted',['window_id'=>$wid,'before'=>$before,'reason'=>$reason]);
  }elseif(in_array($action,['sa_window_create','sa_window_edit'],true)){$year=acText($p,'academic_year',20);acAssert(preg_match('/^(20\d{2})-(20\d{2})$/',$year,$m)===1&&(int)$m[2]===(int)$m[1]+1,'Use consecutive academic years, e.g. 2026-2027.');$semester=acText($p,'semester',4);acAssert(in_array($semester,['I','II'],true),'Select semester I or II.');$programme=trim($p['programme']??'');acAssert($programme===''||in_array($programme,examProgrammes(),true),'Unknown programme.');$a=str_replace('T',' ',acText($p,'opens_at',20));$b=str_replace('T',' ',acText($p,'closes_at',20));acAssert(acDateTimeValid($a)&&acDateTimeValid($b)&&$b>$a,'Choose valid opening and closing dates.');if($action==='sa_window_edit'){
   q('UPDATE student_attendance_windows SET title=?,academic_year=?,semester=?,programme=?,opens_at=?,closes_at=? WHERE id=?',[acText($p,'title'),$year,$semester,$programme,$a.':00',$b.':00',$wid]);
   acAudit($u,0,'Attendance submission period edited',['window_id'=>$wid,'before'=>$before,'after'=>one('SELECT * FROM student_attendance_windows WHERE id=?',[$wid]),'reason'=>$reason]);
  }else q('INSERT INTO student_attendance_windows(title,academic_year,semester,programme,opens_at,closes_at,created_by,created_at) VALUES(?,?,?,?,?,?,?,?)',[acText($p,'title'),$year,$semester,$programme,$a.':00',$b.':00',$u['id'],now()]);if($action==='sa_window_create'){$wid=(int)db()->lastInsertId();acAudit($u,0,'Attendance submission period opened',['window_id'=>$wid,'settings'=>array_diff_key($p,['csrf'=>true])]);}}
  else{$wid=(int)($p['window_id']??0);acAssert((bool)one('SELECT id FROM student_attendance_windows WHERE id=?',[$wid]),'Period not found.');q('UPDATE student_attendance_windows SET enabled=? WHERE id=?',[($p['enabled']??'')==='1'?1:0,$wid]);acAudit($u,0,'Attendance submission period changed',['window_id'=>$wid,'enabled'=>($p['enabled']??'')==='1']);}$id=0;
 }else{
  $id=(int)($p['id']??0);$raw=one("SELECT * FROM academic_records WHERE id=? AND kind='attendance'".(db()->getAttribute(PDO::ATTR_DRIVER_NAME)==='mysql'?' FOR UPDATE':''),[$id]);acAssert((bool)$raw,'Attendance module not found.');$r=acHydrate($raw);acAssert($r['status']==='Submitted'||acAdmin($u),'Submit the draft first.');acAssert((int)($p['revision']??0)===(int)$r['revision'],'Record changed. Reload before saving.');
  if($action==='sa_append'){$u=saTutor();acAssert($u&&(acAdmin($u)||(int)$u['id']===(int)$r['owner_id']),'Verify the original tutor email to add attendance.');if(!acAdmin($u))saWindow($r,(int)($p['window_id']??0),true);$new=saParseMatrix($r,saReadFile($_FILES['sheet']??[]));$entries=saMerge($r,$r['entries'],$new,true);acValidateEntries($r,$entries,true);acAssert(($p['confirmed']??'')==='1','Confirm that the additional attendance is correct.');if(acJson($entries)!==acJson($r['entries'])){q('UPDATE academic_records SET entries=?,revision=revision+1,updated_at=? WHERE id=?',[acJson($entries),now(),$id]);acAudit($u,$id,'Attendance added',['window_id'=>(int)$p['window_id'],'previous_rows'=>count($r['entries']),'rows'=>count($entries)]);}}
  elseif($action==='sa_correct'){acAssert(saReviewer($u),'Only Admin / Exam Cell / DAA can edit submitted attendance.');$reason=acText($p,'reason',1000);$hours=acNumber($p['contact_hours']??'','DPD contact hours',0.01,2000);$entries=$r['entries'];if(($_FILES['sheet']['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_NO_FILE)$entries=saParseMatrix($r,saReadFile($_FILES['sheet']));acValidateEntries($r,$entries,true);q('UPDATE academic_records SET entries=?,contact_hours=?,revision=revision+1,updated_at=? WHERE id=?',[acJson($entries),$hours,now(),$id]);acAudit($u,$id,'Attendance corrected',['before'=>$r['entries'],'after'=>$entries,'old_hours'=>$r['contact_hours'],'new_hours'=>$hours,'reason'=>$reason]);}
  elseif($action==='sa_verify'){acAssert(saReviewer($u),'Only Admin / Exam Cell / DAA can verify supporting documents.');$sid=acText($p,'student_id',60);$student=null;foreach(acAttendance($r)['students']as $candidate)if((string)$candidate['id']===$sid)$student=$candidate;acAssert((bool)$student,'Student not found.');$percent=acRecordedPercent($student);acAssert($percent!==null,'No recorded sessions.');acAssert($percent>=80&&$percent<90,'Verification applies only to attendance of 80% to below 90%.');$decision=$p['decision']??'';acAssert(in_array($decision,['Approved','Rejected'],true),'Choose a verification decision.');$reason=acText($p,'reason',1000);$file=$_FILES['support']??[];acAssert(($file['error']??1)===UPLOAD_ERR_OK&&$file['size']<=10*1024*1024&&is_uploaded_file($file['tmp_name']),'Attach a supporting PDF up to 10 MB.');acAssert((new finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name'])==='application/pdf'&&str_starts_with(file_get_contents($file['tmp_name'],false,null,0,5),'%PDF-'),'Supporting document must be a PDF.');$dir=__DIR__.'/../../storage/attendance-support';if(!is_dir($dir))acAssert(mkdir($dir,0700,true),'Unable to create protected storage.');$key=bin2hex(random_bytes(24)).'.pdf';acAssert(move_uploaded_file($file['tmp_name'],$dir.'/'.$key),'Unable to store document.');chmod($dir.'/'.$key,0600);q('INSERT INTO student_attendance_verifications(record_id,student_id,record_revision,decision,document_path,reason,actor_id,created_at) VALUES(?,?,?,?,?,?,?,?)',[$id,$sid,$r['revision'],$decision,$key,$reason,$u['id'],now()]);acAudit($u,$id,'Attendance supporting document verified',['student_id'=>$sid,'decision'=>$decision,'reason'=>$reason]);}
  else throw new RuntimeException('Unknown attendance action.');
 }db()->commit();return $id;
 }catch(Throwable $e){if(db()->inTransaction())db()->rollBack();if(isset($key,$dir)&&is_file($dir.'/'.$key))unlink($dir.'/'.$key);throw $e;}
}
function saEligibility(array $r,array $s):string{
 $percent=acRecordedPercent($s);if($percent===null)return 'No recorded sessions';if($percent<80)return 'Not allowed to sit the exam';if($percent>=90)return 'Allowed to sit the exam';
 $v=saReady()?one('SELECT * FROM student_attendance_verifications WHERE record_id=? AND student_id=? AND record_revision=? ORDER BY id DESC LIMIT 1',[$r['id'],$s['id'],$r['revision']]):null;
 return !$v?'Supporting document and verification required':($v['decision']==='Approved'?'Allowed — supporting document verified':'Not allowed — verification rejected');
}
function saDownload(?array $official):never{
 acAssert(saReady(),'Attendance setup required.');$id=(int)($_GET['id']??0);$r=one("SELECT * FROM academic_records WHERE id=? AND kind='attendance'",[$id]);acAssert((bool)$r,'Module not found.');$r=acHydrate($r);$tutor=saTutor();$owner=$tutor&&(int)$r['owner_id']===(int)$tutor['id'];$review=acAdmin($official)||(saReviewer($official)&&$r['status']==='Submitted');$mode=$_GET['mode']??'template';acAssert($review||$owner,'Access denied.');
 if($mode==='support'){acAssert($review,'Only Admin / Exam Cell / DAA can download supporting documents.');$v=one('SELECT * FROM student_attendance_verifications WHERE id=? AND record_id=?',[(int)($_GET['document_id']??0),$id]);acAssert((bool)$v,'Document not found.');header('Content-Type: application/pdf');header('Content-Disposition: attachment; filename="attendance-support.pdf"');readfile(__DIR__.'/../../storage/attendance-support/'.$v['document_path']);exit;}
 acAssert($mode==='template'||$review||($owner&&$r['status']==='Draft'),'Submitted student entries are restricted to Exam Cell / DAA.');$rows=saMatrix($r,$mode==='template');
 if(($_GET['format']??'')==='csv'){header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="attendance-register.csv"');$f=fopen('php://output','w');fwrite($f,"\xEF\xBB\xBF");foreach($rows as $row)fputcsv($f,array_map(fn($v)=>preg_match('/^[=+@\-\t\r]/',(string)$v)?"'".$v:$v,$row));exit;}
 $book=new \PhpOffice\PhpSpreadsheet\Spreadsheet();$sheet=$book->getActiveSheet()->setTitle('Register');foreach($rows as $i=>$row)foreach($row as $j=>$v)$sheet->setCellValueExplicit([$j+1,$i+1],(string)$v,\PhpOffice\PhpSpreadsheet\Cell\DataType::TYPE_STRING);$sheet->freezePane('D5');$last=\PhpOffice\PhpSpreadsheet\Cell\Coordinate::stringFromColumnIndex(count($rows[1]));$sheet->getStyle('A1:'.$last.'4')->getFont()->setBold(true)->getColor()->setARGB('FFFFFFFF');$sheet->getStyle('A1:'.$last.'4')->getFill()->setFillType('solid')->getStartColor()->setARGB('FF164D72');$sheet->getColumnDimension('A')->setWidth(10);$sheet->getColumnDimension('B')->setWidth(20);$sheet->getColumnDimension('C')->setWidth(30);for($c=4;$c<=count($rows[1]);$c++)$sheet->getColumnDimension(\PhpOffice\PhpSpreadsheet\Cell\Coordinate::stringFromColumnIndex($c))->setWidth(18);
 // Merge date headings for the same day, matching the printed attendance register.
 $dateCells=array_slice($rows[0],3);for($c=0;$c<count($dateCells);){$span=1;while(isset($dateCells[$c+$span])&&($mode==='template'||$dateCells[$c+$span]===$dateCells[$c]))$span++;if($span>1)$sheet->mergeCells([$c+4,1,$c+$span+3,1]);$c+=$span;}
 // Provide visible writing rows even in a new, empty template; blank rows are ignored on import.
 $endRow=$mode==='template'?34:max(4,count($rows));
 $sheet->getStyle('A1:'.$last.$endRow)->getBorders()->getAllBorders()->setBorderStyle('thin')->getColor()->setARGB('FF9CB1C5');
 $sheet->getStyle('A1:'.$last.$endRow)->getAlignment()->setVertical('center');
 $sheet->getStyle('D1:'.$last.$endRow)->getAlignment()->setHorizontal('center');
 $sheet->getStyle('A1:'.$last.'4')->getAlignment()->setWrapText(true);
 for($row=1;$row<=$endRow;$row++){$sheet->getRowDimension($row)->setRowHeight($row<=4?30:24);if($row>=5&&$row%2===0)$sheet->getStyle('A'.$row.':'.$last.$row)->getFill()->setFillType('solid')->getStartColor()->setARGB('FFF2F6FB');}
 $sheet->getStyle('B5:B'.$endRow)->getNumberFormat()->setFormatCode('@');
 $sheet->getPageSetup()->setOrientation('landscape')->setFitToWidth(1)->setFitToHeight(0)->setRowsToRepeatAtTopByStartAndEnd(1,4);
 if($review&&$mode!=='template'){$summary=[];$report=acAttendance($r);foreach($report['students']as $student)$summary[]=[count($summary)+1,$student['id'],$student['name'],$r['contact_hours'],$student['present'],$student['absent'],$student['extra_present'],$student['percentage'],$student['recorded_percentage'],saEligibility($r,$student),$report['complete']?'Complete recorded coverage':'Provisional: check missing uploads'];acWriteSheet($book->createSheet()->setTitle('Eligibility'),['Sl. No.','Student ID','Student Name','DPD hours','Present','Absent','Extra class','Attendance % (DPD)','Recorded-session %','Remarks','DPD coverage'],$summary);}
 $info=$book->createSheet()->setTitle('Instructions');$lines=[$r['module_code'].' · '.$r['module_name'],$r['programme'].' · '.$r['academic_year'].' · Year '.$r['study_year'].' · Semester '.$r['semester'].' · Section '.$r['section'],'DPD hours: '.$r['contact_hours'],'Enter ISO dates (YYYY-MM-DD) in row 1. Repeat the date over each period, or leave cells blank after the first date in a group.','Copy period columns to the right for more dates. Keep the first four rows and the first three columns.','One student per row from row 5. Use P or A. Unused periods must be blank for every student.','Class Type is Regular or Extra. Exam eligibility uses present / recorded sessions (including Extra) x 100. DPD percentage is for reference only.','Use Add attendance for a later upload to the same module. Identical cells are ignored; different previously submitted cells require Exam Cell / DAA correction.','Maximum 400 period columns, 200,000 cells per file and 5,000 student/date/type entries per module.'];foreach($lines as $i=>$line)$info->setCellValueExplicit([1,$i+1],$line,\PhpOffice\PhpSpreadsheet\Cell\DataType::TYPE_STRING);$info->getColumnDimension('A')->setWidth(120);$book->setActiveSheetIndex(0);header('Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');header('Content-Disposition: attachment; filename="attendance-register.xlsx"');(new \PhpOffice\PhpSpreadsheet\Writer\Xlsx($book))->save('php://output');exit;
}
